select author, year, count(title) from (SELECT "_key" AS _key, "address" AS address, "booktitle" AS booktitle, "chapter" AS chapter, "ee" AS ee, "isbn" AS isbn, "journal" AS journal, "mdate" AS mdate, "month" AS month, "number" AS number, "pages" AS pages, "publisher" AS publisher, "publtype" AS publtype, "title" AS title, "type" AS type, "url" AS url, "volume" AS volume, "year" AS year, "author" AS author, "cdrom" AS cdrom, "cite" AS cite, "crossref" AS crossref, "editor" AS editor, "note" AS note, "school" AS school, "series" AS series FROM read_parquet_flat('dblp.parquet')) where title like '%database%' or title like '%text%' or title like '%mining%' group by author, year
